(()=>{const image=document.querySelector('.hero-art img');document.querySelectorAll('[data-landscape]').forEach(button=>{button.addEventListener('click',()=>{image.src='assets/brand/'+button.dataset.landscape;image.alt=button.dataset.landscape==='chillar-canyon.webp'?'Recreación visual de un arroyo entre rocas y vegetación, inspirada en el Río Chíllar':'Recreación visual del agua entre rocas del proyecto TERRA BEATS';document.querySelectorAll('[data-landscape]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))})})})();
